<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';Auth::requirePermission('docs.manage');$pageTitle='گزارش مطالعه مستندات';$adminExtraStylesheets=['/assets/css/workforce.css'];$docId=(int)($_GET['doc_id']??0);$where=$docId?' WHERE l.doc_id=?':'';$logs=Database::fetchAll('SELECT l.*,a.title doc_title,u.name user_name,u.employee_no,ou.title unit_title FROM docs_read_logs l JOIN docs_articles a ON a.id=l.doc_id JOIN users u ON u.id=l.user_id LEFT JOIN org_units ou ON ou.id=u.org_unit_id'.$where.' ORDER BY l.read_at DESC',$docId?[$docId]:[]);$docs=Database::fetchAll('SELECT id,title FROM docs_articles ORDER BY title');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>گزارش مطالعه</h1><p>مشاهده و تایید مطالب آموزشی</p></div><a class="btn" href="/admin/docs.php">مستندات</a></div><nav class="workforce-tabs"><a href="/admin/docs.php">مستندات</a><a href="/admin/docs-categories.php">دسته‌بندی‌ها</a><a class="is-active" href="/admin/docs-view-logs.php">گزارش مطالعه</a></nav><section class="card"><form method="get" class="form-actions"><select name="doc_id"><option value="">همه مستندات</option><?php foreach($docs as $d):?><option value="<?=$d['id']?>" <?=$docId===$d['id']?'selected':''?>><?=e($d['title'])?></option><?php endforeach?></select><button class="btn btn-primary">فیلتر</button></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>مستند</th><th>کاربر</th><th>واحد</th><th>مشاهده</th><th>تایید</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['doc_title'])?></td><td><?=e($l['user_name'].' — '.($l['employee_no']?:'بدون شماره'))?></td><td><?=e($l['unit_title']?:'—')?></td><td><?=e(format_jalali_date($l['read_at']))?></td><td><?=e($l['confirmed_at']?format_jalali_date($l['confirmed_at']):'تایید نشده')?></td></tr><?php endforeach?><?php if(!$logs):?><tr><td colspan="5">گزارشی ثبت نشده است.</td></tr><?php endif?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
